-- The sheet's policy versions: every change to a policy setting (the rounding mode, the floor, the cap, the terms, the late
-- percent or the clerk limit) is a new version, numbered from 1 in the order made, with the setting changed and the date
-- it is in force from (null: none, it counts always).
CREATE TABLE policy_version (
    sheet_id VARCHAR(100) NOT NULL,
    number INT NOT NULL,
    setting_key VARCHAR(100) NOT NULL,
    from_date DATE
);
CREATE INDEX policy_version_sheet ON policy_version (sheet_id, number);
-- The value each policy version set its setting to (null: blank).
ALTER TABLE policy_version ADD COLUMN setting_value VARCHAR(100);
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.List;

/**
 * A version of the sheet's policy: every change to one of its policy settings (the rounding mode, the floor, the cap, the
 * terms, the late percent and the clerk limit) is a new one, numbered from 1 in the order made, in force from the
 * from-date it was saved with (null: none, it counts always), setting its key to the value (null: blank).
 */
public record PolicyVersion(int number, String key, LocalDate from, String value) {

    /** The version in force on the date: how many versions are from a date on or before it (one with none counts always). */
    public static int inForce(List<PolicyVersion> versions, LocalDate date) {
        return (int) versions.stream().filter((v) -> v.from() == null || (date != null && !v.from().isAfter(date))).count();
    }
}
